  Lemma r180_E : forall regs m (s : Z) (ret v8 v9 : word),
    (32 <= s)%Z -> (s < 2 ^ 64)%Z ->
    cellsZ m [(s - 8, ret); (s - 16, v8); (s - 24, v9)]%Z ->
    rdn SEGS m (Z_to_bv 64 0x1125c8) 8 = Some (Z_to_le_bytes 8 0x1137b8) -> rdn SEGS m (Z_to_bv 64 0x1137b8) 4 = Some (Z_to_le_bytes 4 3) ->
    getr regs 2 = Z_to_bv 64 (s - 32) -> getr regs 10 = Z_to_bv 64 0 ->
    exists regs',
      msteps SEGS (mkst regs (0x88378 : word) m rom) (mkst regs' (0x6311c : word) m rom)
      /\ getr regs' 2 = Z_to_bv 64 s /\ getr regs' 1 = ret /\ getr regs' 8 = v8 /\ getr regs' 9 = v9
      /\ getr regs' 10 = Z_to_bv 64 0x126da /\ getr regs' 11 = Z_to_bv 64 0x13dec /\ getr regs' 12 = Z_to_bv 64 0
      /\ regs_agree (fun r => In r [1; 2; 8; 9; 10; 11; 12]%list) regs regs'.
